// Helper normalization function for strings to ensure "Days first, Nights second"
export const normalizeDurationOrder = (text: string): string => {
    if (!text) return text;
    let newText = text;

    // 1. Matches "X Nights / Y Days", "X Nights Y Days", "X Night / Y Days", etc.
    newText = newText.replace(/(\d+)\s*Nights?\s*[\/\-\?\s]*\s*(\d+)\s*Days?/gi, (match, n, d) => {
        const nights = parseInt(n, 10);
        const days = parseInt(d, 10);
        return `${days} Days / ${nights} Night${nights > 1 ? 's' : ''}`;
    });

    // 2. Matches "X Nights Y Days" without slashes
    newText = newText.replace(/(\d+)\s*Nights?\s+(\d+)\s*Days?/gi, (match, n, d) => {
        const nights = parseInt(n, 10);
        const days = parseInt(d, 10);
        return `${days} Days ${nights} Night${nights > 1 ? 's' : ''}`;
    });

    // 3. Matches "X Nights Y Days" or "X Night 2 Days" with simple spaces
    newText = newText.replace(/(\d+)\s*Night\s+(\d+)\s*Day/gi, (match, n, d) => {
        const nights = parseInt(n, 10);
        const days = parseInt(d, 10);
        return `${days} Day / ${nights} Night`;
    });

    // 4. Matches "XN YD", "XN/YD", "Xn/Yd"
    newText = newText.replace(/(\d+)\s*[nN]\s*[\/\-–\s]*\s*(\d+)\s*[dD]/g, '$2D / $1N');

    return newText;
};

// Apply dynamic normalization to all packagesDatabase elements on initialization
Object.keys(packagesDatabase).forEach(key => {
    const p = packagesDatabase[key];
    if (!p) return;
    if (p.title) p.title = normalizeDurationOrder(p.title);
    if (p.overview && p.overview.duration) p.overview.duration = normalizeDurationOrder(p.overview.duration);
    if (p.keywords) p.keywords = normalizeDurationOrder(p.keywords);
});

export const getPackageDisplayTitle = (p: any): string => {
    if (!p) return '';
    return normalizeDurationOrder(p.title);
};

export const getPackageCategory = (pkg: any) => {
    if (!pkg) return { name: 'Tours', slug: 'tours' };

    const idNum = parseInt(pkg.id);
    const titleLower = (pkg.title || '').toLowerCase();
    const destLower = (pkg.overview?.destination || '').toLowerCase();

    // Honeymoon Packages by ID ranges
    if (idNum >= 9000 && idNum <= 9099) return { name: 'Kerala Honeymoon Packages', slug: 'kerala-honeymoon-packages' };
    if (idNum >= 9100 && idNum <= 9199) return { name: 'Goa Honeymoon Packages', slug: 'goa-honeymoon-packages' };
    if (idNum >= 9200 && idNum <= 9299) return { name: 'Tamil Nadu Honeymoon Packages', slug: 'tamil-nadu-honeymoon-packages' };
    if (idNum >= 9300 && idNum <= 9399) return { name: 'Karnataka Honeymoon Packages', slug: 'karnataka-honeymoon-packages' };
    if (idNum >= 9400 && idNum <= 9499) return { name: 'Kashmir Honeymoon Packages', slug: 'kashmir-honeymoon-packages' };
    if (idNum >= 9500 && idNum <= 9599) return { name: 'Himachal Honeymoon Packages', slug: 'himachal-honeymoon-packages' };
    if (idNum >= 9600 && idNum <= 9699) return { name: 'Andaman Honeymoon Packages', slug: 'andaman-honeymoon-packages' };
    if (idNum >= 9700 && idNum <= 9799) return { name: 'Sikkim Darjeeling Honeymoon Packages', slug: 'sikkim-darjeeling-honeymoon-packages' };
    if (idNum >= 9800 && idNum <= 9899) return { name: 'Maldives Honeymoon Packages', slug: 'maldives-honeymoon-packages' };

    // Golden Triangle Tours
    const goldenTriangleIds = [8001, 8002, 8003, 8004, 8005, 8006, 8008];
    if (goldenTriangleIds.includes(idNum)) {
        return { name: 'Golden Triangle Tours', slug: 'golden-triangle-tours' };
    }

    // Delhi Tours
    const delhiTourIds = [8007, 8009, 8010, 8011];
    if (delhiTourIds.includes(idNum)) {
        return { name: 'Delhi Tours', slug: 'delhi-tours' };
    }

    // Madurai Tours: 2025 to 2099, or containing specific keywords
    const maduraiKeywords = ['madurai', 'kumbakonam', 'trichy', 'thiruchendur', 'megamalai', 'thanjavur'];
    if ((idNum >= 2025 && idNum <= 2099) || maduraiKeywords.some(kw => titleLower.includes(kw) || destLower.includes(kw))) {
        return { name: 'Madurai Tours', slug: 'madurai-tours' };
    }

    // Shirdi Tours
    if (titleLower.includes('shirdi') || destLower.includes('shirdi') || (idNum >= 2011 && idNum <= 2024)) {
        return { name: 'Shirdi Tours', slug: 'shirdi-tours' };
    }

    // Varanasi Tours
    if (titleLower.includes('varanasi') || titleLower.includes('kasi') || destLower.includes('varanasi') || (idNum >= 2001 && idNum <= 2010)) {
        return { name: 'Varanasi Tours', slug: 'varanasi-tours' };
    }

    // Ayodhya Tours
    if (titleLower.includes('ayodhya') || destLower.includes('ayodhya')) {
        return { name: 'Ayodhya Tours', slug: 'ayodhya-tours' };
    }

    // Rameshwaram Tours
    if (titleLower.includes('rameshwaram') || destLower.includes('rameshwaram') || idNum === 42) {
        return { name: 'Rameshwaram Tours', slug: 'rameshwaram-tours' };
    }

    // Kanyakumari Tours
    if (titleLower.includes('kanyakumari') || destLower.includes('kanyakumari')) {
        return { name: 'Kanyakumari Tours', slug: 'kanyakumari-tours' };
    }

    // Kerala Tours
    const keralaKeywords = ['munnar', 'thekkady', 'alleppey', 'vagamon', 'valparai', 'kumarakom', 'marayoor', 'kerala'];
    if (keralaKeywords.some(kw => titleLower.includes(kw) || destLower.includes(kw))) {
        return { name: 'Kerala Tours', slug: 'kerala-tours' };
    }

    // Fallback: detect single words in destination or title
    if (destLower.includes('pune')) return { name: 'Pune Tours', slug: 'pune-tours' };
    if (destLower.includes('cherrapunji')) return { name: 'Cherrapunji Tours', slug: 'cherrapunji-tours' };
    if (destLower.includes('shillong')) return { name: 'Shillong Tours', slug: 'shillong-tours' };
    if (destLower.includes('guwahati')) return { name: 'Guwahati Tours', slug: 'guwahati-tours' };

    // Shimla Tours
    if ((idNum >= 8100 && idNum <= 8199) || titleLower.includes('shimla') || destLower.includes('shimla')) {
        return { name: 'shimla-tours', slug: 'shimla-tours' };
    }

    // Manali Tours
    if ((idNum >= 8200 && idNum <= 8399) || titleLower.includes('manali') || destLower.includes('manali')) {
        return { name: 'manali-tours', slug: 'manali-tours' };
    }

    // Kashmir Tours
    if ((idNum >= 8400 && idNum <= 8499) || titleLower.includes('kashmir') || destLower.includes('kashmir')) {
        return { name: 'kashmir-tours', slug: 'kashmir-tours' };
    }

    // Andaman Tours
    if (titleLower.includes('andaman') || destLower.includes('andaman')) {
        return { name: 'Andaman Tours', slug: 'andaman-tours' };
    }

    return { name: 'Tours', slug: 'tours' };
};

export const getPackageLink = (pkg: any) => {
    if (!pkg) return '/tour-packages';
    const categoryInfo = getPackageCategory(pkg);

    // Decide route prefix based on category
    const northIndiaKeywords = ['varanasi', 'shirdi', 'ayodhya', 'guwahati', 'pune', 'cherrapunji', 'shillong'];
    const routePrefix = northIndiaKeywords.includes(categoryInfo.slug.replace('-tours', ''))
        ? 'north-india-tour-packages'
        : 'tour-packages';

    return `/${routePrefix}/${categoryInfo.slug}/${generateSlug(pkg.title)}`;
};

